import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "calculator",
  name: "Calculator",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "tool",
      tool: {
        name: "sum_values",
        version: "1.0.0",
        description: "Sum a list of numbers and return the total.",
        permissions: [],
        sideEffect: "none",
        parameters: {
          type: "object",
          properties: {
            numbers: {
              type: "array",
              items: { type: "number" },
              description: "The numbers to sum.",
            },
          },
          required: ["numbers"],
        },
        outputSchema: {
          type: "object",
          properties: {
            sum: { type: "number" },
            count: { type: "integer" },
          },
          required: ["sum", "count"],
        },
        async handler(args, tctx) {
          const numbers = args?.numbers;
          if (!Array.isArray(numbers)) {
            return { ok: false, error: "numbers must be an array" };
          }
          let sum = 0;
          for (const n of numbers) {
            if (typeof n !== "number" || Number.isNaN(n)) {
              return { ok: false, error: "all items must be finite numbers" };
            }
            sum += n;
          }
          return { ok: true, data: { sum, count: numbers.length } };
        },
      },
    });
  },
};

export default plugin;

